#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> sequentialDigits(int low, int high) {
        std::string s = "123456789";
        std::vector<int> res;
        for (int len = 1; len <= 9; ++len) {
            for (int start = 0; start <= 9 - len; ++start) {
                int val = std::stoi(s.substr(start, len));
                if (val >= low && val <= high) {
                    res.push_back(val);
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> sequentialDigits(int low, int high) {
        String s = "123456789";
        List<Integer> res = new ArrayList<>();
        for (int len = 1; len <= 9; len++) {
            for (int start = 0; start <= 9 - len; start++) {
                int val = Integer.parseInt(s.substring(start, start + len));
                if (val >= low && val <= high) {
                    res.add(val);
                }
            }
        }
        return res;
    }
}

var sequentialDigits = function(low, high) {
    const s = "123456789";
    const res = [];
    for (let len = 1; len <= 9; len++) {
        for (let start = 0; start <= 9 - len; start++) {
            const val = parseInt(s.substring(start, start + len), 10);
            if (val >= low && val <= high) {
                res.push(val);
            }
        }
    }
    return res;
};
